    # Uniform lines mark tile boundaries.
    row_lines = [r for r in range(h) if len(set(grid[r])) == 1]
    col_lines = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    row_sep_colors = {grid[r][0] for r in row_lines}
    col_sep_colors = {grid[0][c] for c in col_lines}
    sep_colors = row_sep_colors | col_sep_colors

    # Divide into regions between the separator lines.
    def regions(length, lines):
        bounds = [-1] + lines + [length]
        return [(a + 1, b) for a, b in zip(bounds, bounds[1:]) if a + 1 < b]

    rs = regions(h, row_lines)
    cs = regions(w, col_lines)

    # Background is the most frequent non-separator color.
    counts = {}
    for row in grid:
        for v in row:
            if v not in sep_colors:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get) if counts else 0

    # Find the region containing the densest non-background pattern.
    best = None
    best_count = -1
    for r0, r1 in rs:
        for c0, c1 in cs:
            cells = [(r - r0, c - c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != bg and grid[r][c] not in sep_colors]
            if len(cells) > best_count:
                best_count = len(cells)
                best = cells

    out = [row[:] for row in grid]
    if best:
        for r0, r1 in rs:
            for c0, c1 in cs:
                for dr, dc, value in best:
                    if r0 + dr < r1 and c0 + dc < c1:
