    # Uniform lines of the less-common color are dividers; frequent uniform
    # background lines are not.
    row_colors = {}
    col_colors = {}
    for r in range(h):
        if len(set(grid[r])) == 1:
            v = grid[r][0]
            row_colors[v] = row_colors.get(v, 0) + 1
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            v = next(iter(vals))
            col_colors[v] = col_colors.get(v, 0) + 1

    row_div = set()
    col_div = set()
    if row_colors:
        v = min(row_colors, key=lambda x: row_colors[x])
        row_div = {r for r in range(h) if all(x == v for x in grid[r])}
    if col_colors:
        v = min(col_colors, key=lambda x: col_colors[x])
        col_div = {c for c in range(w) if all(grid[r][c] == v for r in range(h))}

    divider_colors = set()
    if row_div:
        divider_colors.add(grid[next(iter(row_div))][0])
    if col_div:
        divider_colors.add(grid[0][next(iter(col_div))])

    def bands(n, divs):
        bounds = [-1] + sorted(divs) + [n]
        return [(a + 1, b) for a, b in zip(bounds, bounds[1:]) if a + 1 < b]

    rb, cb = bands(h, row_div), bands(w, col_div)

    # Choose the most frequent non-divider color as the background.
    counts = {}
    for row in grid:
        for v in row:
            if v not in divider_colors:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get) if counts else 0

    # The region with the most non-background cells supplies the motif.
    motif = []
    for r0, r1 in rb:
        for c0, c1 in cb:
            cells = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != bg and grid[r][c] not in divider_colors]
            if len(cells) > len(motif):
                motif = cells

    out = [row[:] for row in grid]
    for r0, r1 in rb:
        for c0, c1 in cb:
            for dr, dc, value in motif:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = value
    return out
